type B=Vec<u32>;
#[derive(Default)]struct A{nodes:Vec<[u32;3]>,memo:HashMap<(u32,u32,u32),u32>,inputs:usize,cutoff:usize}
impl A{fn new()->Self{Self{nodes:vec![[0,0,0],[0,1,0]],..Self::default()}}fn input(&mut self)->u32{let id=self.nodes.len()as u32;self.nodes.push([1,self.inputs as u32,0]);self.inputs+=1;id}fn gate(&mut self,op:u32,mut x:u32,mut y:u32)->u32{if x>y{std::mem::swap(&mut x,&mut y);}if op==2{if x==0{return y;}if x==y{return 0;}}else{if x==0{return 0;}if x==1||x==y{return y;}}if let Some(id)=self.memo.get(&(op,x,y)){return *id;}let id=self.nodes.len()as u32;self.nodes.push([op,x,y]);self.memo.insert((op,x,y),id);id}fn xor(&mut self,x:u32,y:u32)->u32{self.gate(2,x,y)}fn and(&mut self,x:u32,y:u32)->u32{self.gate(3,x,y)}fn eval(&self,inputs:&[bool],eq:&[u32])->bool{assert_eq!(inputs.len(),self.inputs);let mut v=vec![false;self.nodes.len()];v[1]=true;for(i,n)in self.nodes.iter().enumerate().skip(2){v[i]=match n[0]{1=>inputs[n[1]as usize],2=>v[n[1]as usize]^v[n[2]as usize],3=>v[n[1]as usize]&v[n[2]as usize],_=>panic!()};}eq.iter().all(|i|!v[*i as usize])}}

fn trim(mut x:B)->B{while x.last()==Some(&0){x.pop();}x}
fn add(a:&mut A,x:&B,y:&B)->B{let mut z=vec![0;x.len().max(y.len())];for(i,t)in z.iter_mut().enumerate(){*t=a.xor(*x.get(i).unwrap_or(&0),*y.get(i).unwrap_or(&0));}trim(z)}
fn school(a:&mut A,x:&B,y:&B)->B{if x.is_empty()||y.is_empty(){return vec![];}let mut z=vec![0;x.len()+y.len()-1];for(i,x)in x.iter().enumerate(){for(j,y)in y.iter().enumerate(){let p=a.and(*x,*y);z[i+j]=a.xor(z[i+j],p);}}trim(z)}
fn shifted(x:&B,n:usize)->B{if x.is_empty(){return vec![];}let mut out=vec![0;n];out.extend(x);out}
fn mul(a:&mut A,x:&B,y:&B)->B{if x.is_empty()||y.is_empty(){return vec![];}let small=x.len().min(y.len());let big=x.len().max(y.len());if a.cutoff==0||big<=a.cutoff||small<=2{return school(a,x,y);}if big>2*small{let(short,long)=if x.len()<y.len(){(x,y)}else{(y,x)};let mut out=vec![];for(i,part)in long.chunks(small).enumerate(){let p=mul(a,short,&part.to_vec());out=add(a,&out,&shifted(&p,i*small));}return out;}let m=big.div_ceil(2);let x0=x[..m.min(x.len())].to_vec();let x1=x[m.min(x.len())..].to_vec();let y0=y[..m.min(y.len())].to_vec();let y1=y[m.min(y.len())..].to_vec();let z0=mul(a,&x0,&y0);let z2=mul(a,&x1,&y1);let sx=add(a,&x0,&x1);let sy=add(a,&y0,&y1);let mid=mul(a,&sx,&sy);let mid=add(a,&mid,&z0);let mid=add(a,&mid,&z2);let out=add(a,&z0,&shifted(&mid,m));add(a,&out,&shifted(&z2,2*m))}

