fn run(id:&str,path:&str)->Value{let t=Instant::now();let data:Value=serde_json::from_slice(&std::fs::read(path).unwrap()).unwrap();let n=data["extension_field"]["degree"].as_u64().unwrap()as usize;assert_eq!(n,83);let modulus=hx(data["extension_field"]["modulus_hex"].as_str().unwrap());let z=hx(data["target"]["x_hex"].as_str().unwrap());let yt=hx(data["target"]["y_hex"].as_str().unwrap())^&z;let m=Model::new(n,modulus,hx(data["curve"]["a_hex"].as_str().unwrap()),hx(data["curve"]["b_hex"].as_str().unwrap()),z,yt);let basis=data["source_basis_hex"].as_array().unwrap();assert_eq!(basis.len(),18);assert!(hx(data["source_offset_hex"].as_str().unwrap_or("0x0")).is_zero());for(i,x)in basis.iter().enumerate(){assert_eq!(hx(x.as_str().unwrap()),N::one()<<i);}let mut rows=vec![];for cutoff in[0,8]{let s=Instant::now();let(a,eq)=build(&m,18,cutoff);assert_eq!(a.inputs,174);rows.push(json!({"cutoff":cutoff,"counts":reachable(&a,&eq),"compile_seconds_diagnostic":s.elapsed().as_secs_f64(),"profile_complete":true}));}assert!(t.elapsed().as_secs()<65);json!({"schema":"scientific_result_v1","experiment_id":id,"status":"passed","summary":"Complete eliminated binary norm circuit compiled for the actual GF83 fixture with schoolbook and recursive arithmetic.","evidence":{"rows":rows,"scope":"full norm coefficient predicate,174 primary bits, not all-original-root equivalence or a SAT solve","original_root_count_exact":null,"release_gate_claim":false,"novelty_claim":false},"next_actions":["Freeze a native SAT or XOR-solver interface, replay every model against literal norms, and preserve null counts until complete exhaustion.","Recover all ordered original S3 auxiliary fibers and pay ghost/exception coverage before original all-root claims.","Keep genuine F4/F5/F6 full matching and8x gate requirements."]})}
